import React, {
  useState,
  useCallback,
  useEffect,
  createContext,
  useContext,
} from "react";

// --- Domain Imports ---
// These are enums, so they are imported as named exports.
import {
  ProjectStatus,
  EpicStatus,
  StoryStatus,
  Priority,
  RiskLevel,
} from "./domain";

// --- Utility for NotificationService ---
let nextNotificationId = 0;
const generateNotificationId = () => `notification-${nextNotificationId++}`;

// --- 1. ProgressBar Component ---
const ProgressBar = ({ value = 0, color }) => {
  const clampedValue = Math.max(0, Math.min(100, value));

  const getBarColorClass = useCallback(() => {
    if (color) {
      // Use inline style for arbitrary color string to ensure it's applied
      return null;
    }
    if (clampedValue >= 90) return "bg-green-500";
    if (clampedValue >= 50) return "bg-yellow-500";
    if (clampedValue >= 20) return "bg-orange-500";
    return "bg-red-500";
  }, [clampedValue, color]);

  const inlineStyle = color ? { backgroundColor: color } : {};

  return (
    <div className="w-full bg-gray-200 rounded-full h-4 relative overflow-hidden">
      <div
        className={`h-full rounded-full transition-all duration-500 ease-out ${getBarColorClass()}`}
        style={{ width: `${clampedValue}%`, ...inlineStyle }}
      ></div>
      <span className="absolute inset-0 flex items-center justify-center text-xs font-semibold text-gray-800">
        {clampedValue}%
      </span>
    </div>
  );
};

// --- 2. ProgressSlider Component ---
const ProgressSlider = ({ value = 0, onChange, isDisabled = false }) => {
  const clampedValue = Math.max(0, Math.min(100, value));

  const handleChange = useCallback(
    (event) => {
      if (isDisabled) return;
      const newValue = Math.max(
        0,
        Math.min(100, parseInt(event.target.value, 10)),
      );
      if (onChange) {
        onChange(newValue);
      }
    },
    [onChange, isDisabled],
  );

  return (
    <div className="flex items-center space-x-2">
      <input
        type="range"
        min="0"
        max="100"
        value={clampedValue}
        onChange={handleChange}
        className={`w-full h-2 rounded-lg appearance-none cursor-pointer ${
          isDisabled
            ? "opacity-50 cursor-not-allowed bg-gray-300"
            : "bg-blue-500"
        }`}
        disabled={isDisabled}
      />
      <span className="text-sm font-medium text-gray-700 w-10 text-right">
        {clampedValue}%
      </span>
    </div>
  );
};

// --- Helper for Badges (common logic for color mapping) ---
const getBadgeColorClass = (type, value) => {
  switch (type) {
    case "status":
      switch (value) {
        case ProjectStatus.PLANNING:
        case EpicStatus.NOT_STARTED:
        case StoryStatus.NOT_STARTED:
          return "bg-gray-500";
        case ProjectStatus.ACTIVE:
        case EpicStatus.IN_PROGRESS:
        case StoryStatus.IN_PROGRESS:
          return "bg-blue-500";
        case ProjectStatus.COMPLETED:
        case EpicStatus.COMPLETED:
        case StoryStatus.COMPLETED:
          return "bg-green-500";
        case ProjectStatus.PAUSED:
        case EpicStatus.BLOCKED:
        case StoryStatus.BLOCKED:
          return "bg-red-500";
        default:
          return "bg-gray-500";
      }
    case "priority":
      switch (value) {
        case Priority.LOW:
          return "bg-green-500";
        case Priority.MEDIUM:
          return "bg-blue-500";
        case Priority.HIGH:
          return "bg-orange-500";
        case Priority.CRITICAL:
          return "bg-red-500";
        default:
          return "bg-gray-500";
      }
    case "risk":
      switch (value) {
        case RiskLevel.LOW:
          return "bg-green-500";
        case RiskLevel.MEDIUM:
          return "bg-orange-500";
        case RiskLevel.HIGH:
          return "bg-red-500";
        default:
          return "bg-gray-500";
      }
    default:
      return "bg-gray-500";
  }
};

// --- 3. StatusBadge Component ---
const StatusBadge = ({ status }) => {
  const colorClass = getBadgeColorClass("status", status);
  const displayText = status
    ? status
        .replace(/_/g, " ")
        .toLowerCase()
        .replace(/\b\w/g, (char) => char.toUpperCase())
    : "";

  return (
    <span
      className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium text-white ${colorClass}`}
    >
      {displayText}
    </span>
  );
};

