// --- 6. ConfirmationDialog Component ---
const ConfirmationDialog = ({ isOpen, message, onConfirm, onCancel }) => {
  const handleConfirm = useCallback(() => {
    if (onConfirm) {
      onConfirm();
    }
  }, [onConfirm]);

  const handleCancel = useCallback(() => {
    if (onCancel) {
      onCancel();
    }
  }, [onCancel]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-gray-600 bg-opacity-75 flex items-center justify-center z-50">
      <div className="bg-white rounded-lg shadow-xl p-6 max-w-sm mx-auto">
        <p className="text-lg font-semibold text-gray-800 mb-4">{message}</p>
        <div className="flex justify-end space-x-3">
          {onCancel && (
            <button
              onClick={handleCancel}
              className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-200 rounded-md hover:bg-gray-300 focus:outline-none focus:ring-2 focus:ring-gray-500 focus:ring-offset-2"
            >
              Cancel
            </button>
          )}
          <button
            onClick={handleConfirm}
            className="px-4 py-2 text-sm font-medium text-white bg-red-600 rounded-md hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2"
          >
            Confirm
          </button>
        </div>
      </div>
    </div>
  );
};

// --- 7. NotificationService Component & useNotification Hook ---

// Internal NotificationItem component for rendering individual notifications
const NotificationItem = ({ id, message, type, onClose }) => {
  const baseClasses =
    "p-4 mb-2 rounded-md shadow-lg text-white flex items-center justify-between";
  let typeClasses = "";
  switch (type) {
    case "success":
      typeClasses = "bg-green-500";
      break;
    case "error":
      typeClasses = "bg-red-500";
      break;
    case "info":
      typeClasses = "bg-blue-500";
      break;
    case "warning":
      typeClasses = "bg-orange-500";
      break;
    default:
      typeClasses = "bg-gray-500";
  }

  return (
    <div className={`${baseClasses} ${typeClasses}`}>
      <span>{message}</span>
      <button
        onClick={() => onClose(id)}
        className="ml-4 text-white hover:text-gray-200 focus:outline-none"
      >
        &times;
      </button>
    </div>
  );
};

// Context for the notification service
const NotificationContext = createContext(null);

// The NotificationService component (default export)
// This component acts as both the provider and the container for notifications.
export const NotificationService = ({ children }) => {
  const [notifications, setNotifications] = useState([]);

  const addNotification = useCallback((message, type) => {
    const id = generateNotificationId();
    setNotifications((prev) => [...prev, { id, message, type }]);

    // Auto-dismiss after 5 seconds
    const timer = setTimeout(() => {
      setNotifications((prev) => prev.filter((n) => n.id !== id));
    }, 5000);

    // Return a cleanup function for the timer, though not directly used here,
    // it's good practice for managing side effects.
    return () => clearTimeout(timer);
  }, []);

  const removeNotification = useCallback((id) => {
    setNotifications((prev) => prev.filter((n) => n.id !== id));
  }, []);

  // Memoize the context value to prevent unnecessary re-renders
  const contextValue = React.useMemo(
    () => ({
      showSuccess: (message) => addNotification(message, "success"),
      showError: (message) => addNotification(message, "error"),
      showInfo: (message) => addNotification(message, "info"),
      showWarning: (message) => addNotification(message, "warning"),
    }),
    [addNotification],
  );

  return (
    <NotificationContext.Provider value={contextValue}>
      {children}
      <div className="fixed bottom-4 right-4 z-50 w-80">
        {notifications.map((notification) => (
          <NotificationItem
            key={notification.id}
            id={notification.id}
            message={notification.message}
            type={notification.type}
            onClose={removeNotification}
          />
        ))}
      </div>
    </NotificationContext.Provider>
  );
};

// Custom hook for consumers to use the notification service (named export)
export const useNotification = () => {
  const context = useContext(NotificationContext);
  if (!context) {
    // This error indicates the hook is used outside the provider.
    // In a real app, you'd wrap your root component with <NotificationService>.
    throw new Error(
      "useNotification must be used within a NotificationService Provider",
    );
  }
  return context;
};

